import { useCallback, useMemo, useState } from 'react';
import { Button, Calendar, Card, Stack, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
  label?: string;
};

const startOfDay = (date: Date) => {
  const next = new Date(date);
  next.setHours(0, 0, 0, 0);
  return next;
};

const addDays = (date: Date, days: number) => {
  const next = startOfDay(date);
  next.setDate(next.getDate() + days);
  return next;
};

const isSameDay = (left: Date, right: Date) =>
  left.getFullYear() === right.getFullYear() &&
  left.getMonth() === right.getMonth() &&
  left.getDate() === right.getDate();

export default function ReportDatePicker({ value, onChange, label = 'Дата отчёта' }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date>(() => startOfDay(value ?? new Date()));
  const selected = value ? startOfDay(value) : internalDate;

  const presets = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: addDays(today, -1) },
      { id: 'week-ago', label: 'Неделя назад', date: addDays(today, -7) },
    ];
  }, []);

  const select = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setInternalDate(normalized);
      onChange(normalized);
    },
    [onChange],
  );

  return (
    <Card padding="md" style={{ maxWidth: 'var(--jx-size-card-md)' }}>
      <Stack direction="column" gap="md">
        <Text as="h3" size="sm" weight="medium" color="var(--jx-color-text-secondary)">
          {label}
        </Text>

        <Stack direction="row" gap="sm" wrap role="group" aria-label="Быстрый выбор даты">
          {presets.map((preset) => {
            const active = isSameDay(preset.date, selected);
            return (
              <Button
                key={preset.id}
                type="button"
                size="sm"
                variant={active ? 'primary' : 'secondary'}
                aria-pressed={active}
                onClick={() => select(preset.date)}
              >
                {preset.label}
              </Button>
            );
          })}
        </Stack>

        <Calendar value={selected} onChange={select} aria-label={label} />
      </Stack>
    </Card>
  );
}

